(() => {
const svg = document.getElementById('hero'), card = document.getElementById('heroText');
const image = document.createElementNS('http://www.w3.org/2000/svg','image');
image.setAttribute('href','data:image/png;base64,');
image.style.pointerEvents='auto';
image.style.cursor='grab';
svg.replaceChildren(image);
svg.style.filter='none';
let played=false, dragging=false, offsetX=0, offsetY=0;
function layout(){
 const width=Math.min(440,innerWidth-32);
 card.style.width=width+'px'; card.style.maxWidth=width+'px';
 card.style.left=(innerWidth-width)/2+'px';
 card.style.top=(innerHeight-card.offsetHeight)/2+'px';
 svg.setAttribute('viewBox','0 0 '+innerWidth+' '+innerHeight);
 svg.style.width=innerWidth+'px'; svg.style.height=innerHeight+'px';
 const height=innerWidth<700?150:210, figureWidth=height*1086/1448;
 image.setAttribute('width',figureWidth);image.setAttribute('height',height);
 image.setAttribute('x',Math.min(innerWidth-figureWidth-8,(innerWidth+width)/2-figureWidth*.25));
 image.setAttribute('y',Math.max(8,(innerHeight-card.offsetHeight)/2-height+12));
}
function start(replay){
 layout();card.classList.add('on');
 if((replay||!played)&&!matchMedia('(prefers-reduced-motion: reduce)').matches)
 image.animate([{transform:'translateY(-500px)'},{transform:'translateY(0)'}],{duration:850,easing:'cubic-bezier(.35,0,.8,1)'});
 played=true;
}
image.addEventListener('pointerdown',e=>{dragging=true;offsetX=e.clientX-Number(image.getAttribute('x'));offsetY=e.clientY-Number(image.getAttribute('y'));image.setPointerCapture(e.pointerId);e.preventDefault();});
image.addEventListener('pointermove',e=>{if(dragging){image.setAttribute('x',e.clientX-offsetX);image.setAttribute('y',e.clientY-offsetY);}});
image.addEventListener('pointerup',()=>dragging=false);
image.addEventListener('pointercancel',()=>dragging=false);
addEventListener('resize',layout);
window.HERO={start};
if(document.body.dataset.v==='map')start();
})();